const fs = require('fs');
const path = require('path');

const DIST = path.join(__dirname, '..', 'dist');

function norm(s) {
  return String(s || '').replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
}

function isLegacyLabel(text) {
  return /^(?:\d+\s*)?(?:Momento del día|Comida|Ciudad)$/i.test(norm(text));
}

function cleanHtml(html) {
  // Never touch the canonical headings generated by final-guide.js.
  const protectedBlocks = [];
  html = html.replace(/<h3[^>]*class="[^"]*rf-flow-title[^"]*"[^>]*>[\s\S]*?<\/h3>/gi, m => {
    const token = `___RF_CANONICAL_${protectedBlocks.length}___`;
    protectedBlocks.push(m);
    return token;
  });

  // Remove standalone legacy labels, including the numbered labels when the
  // number and label were rendered as separate elements.
  for (let pass = 0; pass < 4; pass++) {
    html = html.replace(/<(div|span|p|strong|b|label|h1|h2|h3|h4|h5|h6)[^>]*>\s*(?:\d+\s*)?(?:Momento del día|Comida|Ciudad)\s*<\/\1>/gi, '');
    html = html.replace(/<(div|span|p|strong|b)[^>]*>\s*\d+\s*<\/\1>/gi, '');
  }

  protectedBlocks.forEach((block, i) => {
    html = html.replace(`___RF_CANONICAL_${i}___`, block);
  });
  return html;
}

function run() {
  const index = path.join(DIST, 'index.html');
  if (!fs.existsSync(index)) return false;
  const html = fs.readFileSync(index, 'utf8');
  fs.writeFileSync(index, cleanHtml(html), 'utf8');
  return true;
}

if (require.main === module) run();
module.exports = { run };
